package com.eatwhat.service;
import com.eatwhat.entity.Dish;
import com.eatwhat.dto.DishWriteRequest;
import com.eatwhat.mapper.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.*;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Real canonical copy, update and receipt services; only persistence is replaced. */
class CatalogQualityCopyContractTest {
 final CanonicalCatalogService catalog=CanonicalTestCatalog.service();final PersonalDishMapper db=mock(PersonalDishMapper.class);final MealConsumptionMapper logs=mock(MealConsumptionMapper.class);final Map<Long,Dish> rows=new HashMap<>();final Map<String,Map<String,Object>> receipts=new HashMap<>();CustomDishService service;
 @BeforeEach void setup(){service=CanonicalTestCatalog.wire(new CustomDishService(mock(DishMapper.class),null,db,logs,CanonicalTestCatalog.JSON),catalog);service.setQuality(CanonicalTestCatalog.quality(catalog));rows.put(1L,CanonicalTestCatalog.dish(1,"糖水","sugar",new BigDecimal("10"),new BigDecimal("2")));when(db.lockReadable(anyLong(),eq(7L))).thenAnswer(c->{Dish d=rows.get(c.getArgument(0));return d==null?null:CanonicalTestCatalog.cloneDish(d);});when(db.insert(any())).thenAnswer(c->{Dish d=c.getArgument(0);d.setId(9L);rows.put(9L,CanonicalTestCatalog.cloneDish(d));return 1;});when(db.update(any())).thenAnswer(c->{Dish d=c.getArgument(0);rows.put(d.getId(),CanonicalTestCatalog.cloneDish(d));return 1;});when(logs.lockUser(7L)).thenReturn(7L);when(logs.request(eq(7L),anyString())).thenAnswer(c->receipts.get(c.getArgument(1)));when(logs.log(eq(7L),anyString(),anyString(),anyString())).thenAnswer(c->{Map<String,Object> receipt=new HashMap<>();receipt.put("requestHash",c.getArgument(2));receipt.put("responseJson",c.getArgument(3));receipts.put(c.getArgument(1),receipt);return 1;});}
 DishWriteRequest request(Dish d,String key){DishWriteRequest r=new DishWriteRequest();r.setRequestId(key);r.setExpectedVersion(d.getContentVersion());r.setRecipe(d.getRecipe().deepCopy());return r;}
 Dish copy(){return service.copyDish(7L,1L,request(rows.get(1L),"copy"));}
 @Test void discretionaryCopyKeepsUnknownAmountsOutOfTotals(){CanonicalTestCatalog.changed(rows.get(1L),r->{ObjectNode i=(ObjectNode)r.path("ingredients").get(0);i.putNull("quantity");i.put("quantityKind","discretionary");i.put("quantityDisplay","适量");});Dish copy=copy();assertNull(copy.getQuality());assertTrue(catalog.scale(copy,new BigDecimal("4")).path("nutrition").path("total").isNull());assertTrue(catalog.scale(copy,new BigDecimal("4")).path("ingredients").get(0).path("quantity").isNull());}
 @Test void copyRebindsIdentityAndNeverChangesSource(){String before=rows.get(1L).getRecipeJson();Dish copy=copy();assertEquals(9,copy.getRecipe().path("id").asInt());assertEquals(before,rows.get(1L).getRecipeJson());assertEquals(10,catalog.scale(copy,new BigDecimal("4")).path("ingredients").get(0).path("quantity").asInt());assertNull(copy.getQuality());}
 @Test void receiptRetryKeepsIdentityWithoutAnotherInsert(){DishWriteRequest r=request(rows.get(1L),"copy");Dish a=service.copyDish(7L,1L,r);rows.remove(1L);Dish b=service.copyDish(7L,1L,r);assertEquals(a.getContentVersion(),b.getContentVersion());verify(db,times(1)).insert(any());}
 @Test void nameAndTimeEditPreservesRecipeAmounts(){Dish copy=copy();DishWriteRequest r=request(copy,"rename");((ObjectNode)r.getRecipe()).put("name","我的糖水");((ObjectNode)r.getRecipe().path("timing")).put("totalMinutes",15);Dish updated=service.updatePersonalDish(7L,9L,r);assertEquals("我的糖水",updated.getName());assertEquals(15,updated.getCookMinutes());assertEquals(10,catalog.scale(updated,new BigDecimal("4")).path("ingredients").get(0).path("quantity").asInt());}
 @Test void ingredientEditUsesOnlyNewCanonicalAmounts(){Dish copy=copy();DishWriteRequest r=request(copy,"amount");((ObjectNode)r.getRecipe().path("ingredients").get(0)).put("quantity",12);Dish updated=service.updatePersonalDish(7L,9L,r);assertEquals(12,catalog.scale(updated,new BigDecimal("4")).path("ingredients").get(0).path("quantity").asInt());assertEquals(10,rows.get(1L).getRecipe().path("ingredients").get(0).path("quantity").asInt());}
 @Test void changedStepsAreSavedWithoutInventingReviewClaims(){Dish copy=copy();DishWriteRequest r=request(copy,"steps");((ObjectNode)r.getRecipe().path("steps").get(0)).put("text","冷水拌匀");Dish updated=service.updatePersonalDish(7L,9L,r);assertEquals("冷水拌匀",updated.getRecipe().path("steps").get(0).path("text").asText());assertNull(updated.getQuality());assertFalse(updated.getRecipeJson().contains("reviewedBy"));}
 @Test void legacyFreeTextCannotOverrideCanonicalAuthoring(){Dish copy=copy();DishWriteRequest r=new DishWriteRequest();r.setRequestId("legacy");r.setExpectedVersion(copy.getContentVersion());r.setCl("柠檬|1|个");clearInvocations(db);assertThrows(IllegalArgumentException.class,()->service.updatePersonalDish(7L,9L,r));verify(db,never()).update(any());}
 @Test void staleVersionCannotOverwriteAnUpdatedCopy(){Dish copy=copy();DishWriteRequest rename=request(copy,"rename");((ObjectNode)rename.getRecipe()).put("name","新名字");service.updatePersonalDish(7L,9L,rename);DishWriteRequest stale=request(copy,"stale");assertThrows(MealConsumptionService.VersionConflict.class,()->service.updatePersonalDish(7L,9L,stale));assertEquals("新名字",rows.get(9L).getRecipe().path("name").asText());}
}
